        // 贪心取 c2 与 b1 同时命中元组；若取 c1 则无元组覆盖，应回退到 c2。
        RepositorySnapshot s = snapshotWithGroups(
                List.of(group("g1", List.of("a", "b", "c"),
                        List.of(Map.of("a", 1, "b", 1, "c", 2)))),
